	@Test
	void aGenuinelySelectiveRangeRetainsItsFirstPosition() throws Exception {
		try (Fixture f = fixture(false, 67, true)) {
			MultiJoinPlan original = (MultiJoinPlan) f.plan;
			RowState row = f.row(f.source, EmptyBindingSet.getInstance());
			long encounterPredicate = f.source.idOf(iri(f.repository.getValueFactory(), "hasEncounter"));
			assertTrue(encounterPredicate != LmdbNativeAggregateCompiler.UNKNOWN);
			PatternPlan encounter = (PatternPlan) Arrays.stream(original.children)
					.filter(child -> child instanceof PatternPlan p && p.p.isConstant() && p.p.constant == encounterPredicate)
					.findFirst().orElseThrow();
			SlotPlan[] order = { original.children[0], encounter };
			SlotPlan[] reverse = { order[1], order[0] };
			PatternPlan ranged = (PatternPlan) order[0], other = (PatternPlan) order[1];
			LmdbNativeWork.Chain forwardQuote = LmdbNativeWork.chain(order, 2, row, 0L);
			LmdbNativeWork.Chain reverseQuote = LmdbNativeWork.chain(reverse, 2, row, 0L);
			NativeLmdbQuerySource.OrderedIntegerDomain domain = f.source.orderedIntegerDomain(
					LmdbNativeAggregateCompiler.UNKNOWN, ranged.p.constant, LmdbNativeAggregateCompiler.UNKNOWN,
					LmdbNativeAggregateCompiler.UNKNOWN, org.eclipse.rdf4j.sail.lmdb.TripleIndex.OBJ_IDX);
			long rangeRows = drain(ranged, row).values().stream().mapToLong(Long::longValue).sum();
			long otherRows = drain(other, row).values().stream().mapToLong(Long::longValue).sum();
			System.out.println("RDF4J_SELECTIVE_RANGE_PREMISE "
					+ "domain=" + domain + ";rangedStatic=" + ranged.staticEstimate + ";otherStatic=" + other.staticEstimate
					+ ";rangedProfile=" + ranged.accessProfile + ";rangeIndex=" + ranged.range.indexFieldSeq()
					+ ";rangeField=" + ranged.range.firstVaryingField() + ";actualRangeRows=" + rangeRows
					+ ";actualOtherRows=" + otherRows + ";rowMask=" + row.boundMask()
					+ ";forward=" + forwardQuote + ";reverse=" + reverseQuote
					+ ";rangedExpected=" + LmdbNativeWork.expectedWork(ranged, row, 0L)
					+ ";otherExpected=" + LmdbNativeWork.expectedWork(other, row, 0L));
			assertEquals(0L, row.boundMask());
			assertEquals(1L, rangeRows, "the real ordered integer range contains only the generated value68");
			assertEquals(4L, otherRows, "the comparison is the real independent four-row encounter relation");
			assertTrue(Double.isFinite(ranged.staticEstimate), "ordinary optimizer metadata must reach the range compiler");
			assertTrue(forwardQuote.estimatedPriceable());
			assertTrue(reverseQuote.estimatedPriceable());
			assertTrue(LmdbNativeWork.chain(order, 2, row, 0L).estimatedWork()
					< LmdbNativeWork.chain(reverse, 2, row, 0L).estimatedWork(),
					"SETUP: the actual finite expected-work quotes must price this selective range first");
			MultiJoinPlan selective = new MultiJoinPlan(order, new MaskedFilter[0]);
			assertSame(selective, LmdbNativeNeutralRangeOrder.prepare(selective, row, 0L));
			Map<List<Long>, Long> rows = drain(selective, row);
			assertEquals(4L, rows.values().stream().mapToLong(Long::longValue).sum());
			assertEquals(0L, row.boundMask());
		}
	}

	@Test
	void anUnpriceableRealPatternChainPreservesItsDeclaredOrder() throws Exception {
		try (Fixture f = fixture(false)) {
			MultiJoinPlan original = (MultiJoinPlan) f.plan;
			RowState row = f.row(f.source, EmptyBindingSet.getInstance());
			List<SlotPlan> members = new ArrayList<>();
			members.add(original.children[0]);
			LmdbNativeWork.Chain quote = LmdbNativeWork.chain(members.toArray(SlotPlan[]::new), members.size(), row, 0L);
			// A bounded control over genuine repeated pattern occurrences, not fabricated IDs or a policy cap.
			for (int count = 0; quote.estimatedPriceable() && count < 2 * Double.MAX_EXPONENT; count++) {
				members.add(original.children[1]);
				quote = LmdbNativeWork.chain(members.toArray(SlotPlan[]::new), members.size(), row, 0L);
			}
			assertTrue(!quote.estimatedPriceable(), "SETUP: repeated actual-source fanout must overflow the point channel");
			MultiJoinPlan unpriced = new MultiJoinPlan(members.toArray(SlotPlan[]::new), new MaskedFilter[0]);
			assertSame(unpriced, LmdbNativeNeutralRangeOrder.prepare(unpriced, row, 0L));
			assertTrue(!unpriced.estimateWork(row, 0L).known(), "an unknown expected price cannot invent a hard quote");
		}
	}


	@Test
	void reducerEncounterDemandsPreserveFloatingTiesAndConcatenation() throws Exception {
		try (Fixture f = fixture(false)) {
			RowState row = f.row(f.source, EmptyBindingSet.getInstance());
			int value = f.layout.slot("value");
			AggregateSpec count = AggregateSpec.slot("r", value, true, AggKind.COUNT);
			assertTrue(count.reducer.canReorderInput());
			assertNotSame(f.plan, LmdbNativeNeutralRangeOrder.prepareAggregate(f.plan, row, 0L,
					new AggregateSpec[] { count }));
			String prefix = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#> ";
			String floating = " WHERE { VALUES ?v { \"1.0E16\"^^xsd:double \"1.0\"^^xsd:double \"-1.0E16\"^^xsd:double } }";
			String tied = " WHERE { VALUES ?v { \"01\"^^xsd:integer \"1\"^^xsd:integer } }";
			AggregateSpec[] sensitive = {
					AggregateSpec.slot("r", value, false, AggKind.SUM),
					AggregateSpec.slot("r", value, false, AggKind.AVG),
					AggregateSpec.slot("r", value, false, AggKind.MIN),
					AggregateSpec.slot("r", value, false, AggKind.MAX),
					AggregateSpec.groupConcat("r", value, false, "|") };
			String[] queries = { prefix + "SELECT (SUM(?v) AS ?r)" + floating,
					prefix + "SELECT (AVG(?v) AS ?r)" + floating,
					prefix + "SELECT (MIN(?v) AS ?r)" + tied,
					prefix + "SELECT (MAX(?v) AS ?r)" + tied,
					"SELECT (GROUP_CONCAT(?v; SEPARATOR=\"|\") AS ?r) WHERE { VALUES ?v { \"b\" \"a\" \"b\" } }" };
			SailRepository memory = new SailRepository(new MemoryStore());
			memory.init();
			try {
				for (int i = 0; i < sensitive.length; i++) {
					AggregateSpec aggregate = sensitive[i];
					assertTrue(!aggregate.reducer.canReorderInput(), aggregate.kind.toString());
					assertSame(f.plan, LmdbNativeNeutralRangeOrder.prepareAggregate(f.plan, row, 0L,
							new AggregateSpec[] { count, aggregate }), "one encounter demand protects the entire input");
					Map<List<String>, Long> ordinary = aggregateBag(memory, queries[i]);
					assertEquals(1L, ordinary.values().stream().mapToLong(Long::longValue).sum());
					List<String> term = ordinary.keySet().iterator().next();
					if (i < 2) assertEquals(0D, Double.parseDouble(term.get(1)));
					else assertEquals(i < 4 ? "01" : "b|a|b", term.get(1),
							"the ordinary owner fixes the tied lexical representative and concatenation sequence");
					assertEquals(ordinary, aggregateBag(f.repository, queries[i]),
							"public owners retain exact domain, lexical, datatype, language and multiplicity");
				}
			} finally {
				memory.shutDown();
			}
			assertSame(f.plan, LmdbNativeNeutralRangeOrder.prepareAggregate(f.plan, row, 0L, null));
			assertSame(f.plan, LmdbNativeNeutralRangeOrder.prepareAggregate(f.plan, row, 0L, new AggregateSpec[0]));
			assertEquals(0L, row.boundMask());
		}
	}

	@Test
	void overwrittenRepeatedAndFailedCopyTargetsDoNotBecomeAssured() throws Exception {
		try (Fixture f = fixture(true)) {
			MultiJoinPlan patterns = (MultiJoinPlan) ((ExtensionPlan) ((ExtensionPlan) f.plan).arg).arg;
			RowState row = f.row(f.source, EmptyBindingSet.getInstance());
			int patient = f.layout.slot("patient"), value = f.layout.slot("value");
			int alias = f.layout.slot("alias"), alias2 = f.layout.slot("alias2");
			ExtensionPlan overwrite = new ExtensionPlan(patterns,
					new CopyBinding[] { CopyBinding.slot(patient, value) });
			assertSame(overwrite, LmdbNativeNeutralRangeOrder.prepare(overwrite, row, 0L));
			assertEquals(Map.of(), drain(overwrite, row), "a failed occupied-slot compatibility write rejects its row");
			ExtensionPlan repeated = new ExtensionPlan(patterns,
					new CopyBinding[] { CopyBinding.slot(alias, value), CopyBinding.slot(alias, value) });
			assertSame(repeated, LmdbNativeNeutralRangeOrder.prepare(repeated, row, 0L),
					"a second write is not a fresh-target proof even if this fixture's values happen to agree");
			assertEquals(8L, drain(repeated, row).values().stream().mapToLong(Long::longValue).sum());
			CopyBinding absent = CopyBinding.slot(alias, alias2);
			absent.assignment = true;
			assertTrue(!absent.setNullOnError);
			ExtensionPlan failed = new ExtensionPlan(patterns, new CopyBinding[] { absent });
			assertSame(failed, LmdbNativeNeutralRangeOrder.prepare(failed, row, 0L));
			assertEquals(drain(patterns, row), drain(failed, row),
					"an absent-source assignment leaves the fresh target absent; an attempted write is not assurance");
			assertEquals(0L, row.boundMask());
		}
	}

	@Test
	void foreignAndUnownedProfilesCannotAuthorizeTheActualPatternOperands() throws Exception {
		try (Fixture f = fixture(false); Fixture foreign = fixture(false)) {
			MultiJoinPlan original = (MultiJoinPlan) f.plan;
			for (SlotPlan child : original.children) assertSame(f.source, ((PatternPlan) child).accessSource);
			assertTrue(f.source.idSpace() != foreign.source.idSpace(), "two genuine stores have distinct ID owners");
			RowState foreignRow = new RowState(foreign.source, f.layout, EmptyBindingSet.getInstance());
			assertTrue(LmdbNativeAggregateCompiler.initializeRow(foreignRow, foreignRow.base, foreign.source, f.layout));
			assertSame(original, LmdbNativeNeutralRangeOrder.prepare(original, foreignRow, 0L));
			PatternPlan pattern = (PatternPlan) original.children[0];
			PatternPlan unowned = new PatternPlan(pattern.s, pattern.p, pattern.o, pattern.c, pattern.contexts,
					pattern.namedContextScope, pattern.statementOrder, pattern.indexName, pattern.range,
					pattern.staticEstimate, pattern.accessProfile);
			assertSame(pattern.accessProfile, unowned.accessProfile);
			assertEquals(null, unowned.accessSource, "a copied profile record does not grant operand ownership");
			SlotPlan[] children = original.children.clone();
			children[0] = unowned;
			MultiJoinPlan noOwner = new MultiJoinPlan(children, original.filters);
			assertSame(noOwner, LmdbNativeNeutralRangeOrder.prepare(noOwner,
					f.row(f.source, EmptyBindingSet.getInstance()), 0L));
			assertEquals(0L, foreignRow.boundMask());
		}
	}

	@Test
	void largeLayoutsAndUnseededPrimitiveCellsKeepTheirOriginalOrder() throws Exception {
		try (Fixture f = fixture(false)) {
			List<String> names = new ArrayList<>(Arrays.asList(f.layout.slotNames()));
			while (names.size() <= Long.SIZE) names.add("unused" + names.size());
			Map<String, Integer> indexes = new LinkedHashMap<>();
			for (int i = 0; i < names.size(); i++) indexes.put(names.get(i), i);
			NativeSlotLayout wide = new NativeSlotLayout(indexes, null);
			wide.freeze(names);
			RowState row = new RowState(f.source, wide, EmptyBindingSet.getInstance());
			assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, f.source, wide));
			assertEquals(Long.SIZE + 1, row.slots.length);
			assertEquals(0L, row.boundMask());
			assertSame(f.plan, LmdbNativeNeutralRangeOrder.prepare(f.plan, row, 0L));
			RowState unseeded = new RowState(f.source, f.layout, EmptyBindingSet.getInstance());
			assertEquals(0L, unseeded.boundMask());
			assertSame(f.plan, LmdbNativeNeutralRangeOrder.prepare(f.plan, unseeded, 0L),
					"a zero bound mask does not authenticate default-zero primitive cells as UNKNOWN");
		}
	}

	private static Map<List<String>, Long> aggregateBag(SailRepository repository, String query) {
		Map<List<String>, Long> result = new LinkedHashMap<>();
		try (var connection = repository.getConnection(); var rows = connection.prepareTupleQuery(query).evaluate()) {
			assertEquals(Set.of("r"), Set.copyOf(rows.getBindingNames()));
			while (rows.hasNext()) {
				BindingSet mapping = rows.next();
				assertEquals(Set.of("r"), mapping.getBindingNames());
				assertTrue(mapping.hasBinding("r"));
				assertTrue(mapping.getValue("r") instanceof Literal);
				Literal literal = (Literal) mapping.getValue("r");
				// These explicit fixtures contain no directional literals. Preserve all their actual RDF fields.
				result.merge(List.of("r", literal.getLabel(), literal.getDatatype().stringValue(),
						literal.getLanguage().orElse("")), 1L, Long::sum);
			}
		}
		return result;
	}

